class AssignmentClosureStatus(str, Enum):
    PENDIENTE_INVENTARIO = "PENDIENTE_INVENTARIO"
    PENDIENTE_DISPOSICION = "PENDIENTE_DISPOSICION"
    LISTA_PARA_CIERRE = "LISTA_PARA_CIERRE"
    CERRADA = "CERRADA"


class BottleDispositionType(str, Enum):
    RETIRO_SOCIO = "RETIRO_SOCIO"
    TRANSFERENCIA_OTRA_CAVA = "TRANSFERENCIA_OTRA_CAVA"
    TRANSFERENCIA_UNIDAD_AUTORIZADA = "TRANSFERENCIA_UNIDAD_AUTORIZADA"
    CONSUMO_TOTAL_CERTIFICADO = "CONSUMO_TOTAL_CERTIFICADO"
    BAJA_AUTORIZADA = "BAJA_AUTORIZADA"


@dataclass(frozen=True)
class CertifiedInventorySnapshot:
    snapshot_id: str
    assignment_id: str
    certified_by_user_id: str
    evidence_reference: str
    bottle_ids: tuple[str, ...]


@dataclass(frozen=True)
class BottleDispositionDecision:
    bottle_id: str
    disposition: BottleDispositionType
    evidence_reference: str
    destination_assignment_id: Optional[str] = None
    destination_unit_id: Optional[str] = None
    authorization_reference: Optional[str] = None


@dataclass(frozen=True)
class AssignmentClosure:
    closure_id: str
    assignment_id: str
    snapshot: CertifiedInventorySnapshot
    dispositions: tuple[BottleDispositionDecision, ...]
    status: AssignmentClosureStatus
    closed_by_user_id: Optional[str] = None


def validate_certified_inventory_snapshot(snapshot: CertifiedInventorySnapshot) -> None:
    for field_name, value in (("snapshot_id", snapshot.snapshot_id), ("assignment_id", snapshot.assignment_id), ("certified_by_user_id", snapshot.certified_by_user_id), ("evidence_reference", snapshot.evidence_reference)):
        if not str(value or "").strip():
            raise ValueError(f"CertifiedInventorySnapshot requiere {field_name}")
    if len(set(snapshot.bottle_ids)) != len(snapshot.bottle_ids):
        raise ValueError("El inventario certificado no puede repetir bottle_id")


def validate_bottle_disposition(decision: BottleDispositionDecision) -> None:
    if not str(decision.bottle_id or "").strip():
        raise ValueError("BottleDispositionDecision requiere bottle_id")
    if not str(decision.evidence_reference or "").strip():
        raise ValueError("Toda disposicion requiere evidence_reference")
    if decision.disposition == BottleDispositionType.TRANSFERENCIA_OTRA_CAVA:
        if not str(decision.destination_assignment_id or "").strip():
            raise ValueError("TRANSFERENCIA_OTRA_CAVA requiere destination_assignment_id")
    if decision.disposition == BottleDispositionType.TRANSFERENCIA_UNIDAD_AUTORIZADA:
        if not str(decision.destination_unit_id or "").strip():
            raise ValueError("TRANSFERENCIA_UNIDAD_AUTORIZADA requiere destination_unit_id")
        if not str(decision.authorization_reference or "").strip():
            raise ValueError("TRANSFERENCIA_UNIDAD_AUTORIZADA requiere authorization_reference")


def validate_assignment_closure(closure: AssignmentClosure) -> None:
    for field_name, value in (("closure_id", closure.closure_id), ("assignment_id", closure.assignment_id)):
        if not str(value or "").strip():
            raise ValueError(f"AssignmentClosure requiere {field_name}")
    validate_certified_inventory_snapshot(closure.snapshot)
    if closure.snapshot.assignment_id != closure.assignment_id:
        raise ValueError("El inventario certificado debe pertenecer a la asignacion que se cierra")
    decisions = {}
    for decision in closure.dispositions:
        validate_bottle_disposition(decision)
        if decision.bottle_id in decisions:
            raise ValueError("Cada botella puede tener una sola disposicion de cierre")
        decisions[decision.bottle_id] = decision
    pending = set(closure.snapshot.bottle_ids) - set(decisions)
    extra = set(decisions) - set(closure.snapshot.bottle_ids)
    if extra:
        raise ValueError("No se puede disponer una botella que no pertenece al inventario certificado")
    if closure.status in {AssignmentClosureStatus.LISTA_PARA_CIERRE, AssignmentClosureStatus.CERRADA} and pending:
        raise ValueError("No se puede cerrar una asignacion con botellas sin disposicion")
    if closure.status == AssignmentClosureStatus.CERRADA and not str(closure.closed_by_user_id or "").strip():
        raise ValueError("CERRADA requiere closed_by_user_id")


def physical_cava_can_be_reassigned(closure: AssignmentClosure) -> bool:
    try:
        validate_assignment_closure(closure)
    except ValueError:
        return False
    return closure.status == AssignmentClosureStatus.CERRADA

import pytest

from modules.cava_socios.domain import (
    AssignmentClosure,
    AssignmentClosureStatus,
    BottleDispositionDecision,
    BottleDispositionType,
    CertifiedInventorySnapshot,
    physical_cava_can_be_reassigned,
    validate_assignment_closure,
    validate_bottle_disposition,
)


def _snapshot():
    return CertifiedInventorySnapshot(
        snapshot_id="SNAP-1",
        assignment_id="ASG-1",
        certified_by_user_id="USR-1",
        evidence_reference="EVID-1",
        bottle_ids=("BOT-1", "BOT-2"),
    )


def test_closure_requires_disposition_for_every_certified_bottle():
    closure = AssignmentClosure(
        closure_id="CLS-1", assignment_id="ASG-1", snapshot=_snapshot(),
        dispositions=(BottleDispositionDecision("BOT-1", BottleDispositionType.RETIRO_SOCIO, "EVID-R1"),),
        status=AssignmentClosureStatus.CERRADA, closed_by_user_id="USR-2",
    )
    with pytest.raises(ValueError):
        validate_assignment_closure(closure)
    assert physical_cava_can_be_reassigned(closure) is False


def test_closed_assignment_with_full_resolution_can_release_physical_cava():
    closure = AssignmentClosure(
        closure_id="CLS-1", assignment_id="ASG-1", snapshot=_snapshot(),
        dispositions=(
            BottleDispositionDecision("BOT-1", BottleDispositionType.RETIRO_SOCIO, "EVID-R1"),
            BottleDispositionDecision("BOT-2", BottleDispositionType.CONSUMO_TOTAL_CERTIFICADO, "EVID-C1"),
        ),
        status=AssignmentClosureStatus.CERRADA, closed_by_user_id="USR-2",
    )
    validate_assignment_closure(closure)
    assert physical_cava_can_be_reassigned(closure) is True


def test_transfer_to_unit_requires_explicit_authorization_and_destination():
    with pytest.raises(ValueError):
        validate_bottle_disposition(BottleDispositionDecision("BOT-1", BottleDispositionType.TRANSFERENCIA_UNIDAD_AUTORIZADA, "EVID-1"))
    validate_bottle_disposition(BottleDispositionDecision("BOT-1", BottleDispositionType.TRANSFERENCIA_UNIDAD_AUTORIZADA, "EVID-1", destination_unit_id="UNIT-1", authorization_reference="AUTH-1"))


def test_transfer_to_other_cava_targets_assignment_not_only_physical_cava():
    with pytest.raises(ValueError):
        validate_bottle_disposition(BottleDispositionDecision("BOT-1", BottleDispositionType.TRANSFERENCIA_OTRA_CAVA, "EVID-1"))
    validate_bottle_disposition(BottleDispositionDecision("BOT-1", BottleDispositionType.TRANSFERENCIA_OTRA_CAVA, "EVID-1", destination_assignment_id="ASG-2"))


def test_time_alone_is_not_a_disposition_type():
    assert "TIMEOUT_AUTOMATICO" not in {item.value for item in BottleDispositionType}
    assert "TRANSFERENCIA_UNIDAD_AUTOMATICA" not in {item.value for item in BottleDispositionType}
